//#CTL2
long customerId;
integer shippedCount;
decimal shippedTotal;
date lastOrderDate;
string[] statuses;

function integer append() {
    customerId = $in.0.customer_id;
    if ($in.0.status == "SHIPPED") {
        shippedCount++;
        shippedTotal = shippedTotal + nvl($in.0.order_amount, 0D);
    }
    if ($in.0.order_date > lastOrderDate) {
        lastOrderDate = $in.0.order_date;
    }
    if (!in($in.0.status, statuses)) {
        push(statuses, $in.0.status);
    }
    return OK;
}

function integer transform() {
    $out.0.customer_id = customerId;
    $out.0.shipped_count = shippedCount;
    $out.0.shipped_total = shippedTotal;
    if (shippedCount > 0) {
        $out.0.avg_shipped = round(shippedTotal / shippedCount, 2);
    } else {
        $out.0.avg_shipped = null;
    }
    $out.0.last_order_date = lastOrderDate;
    $out.0.statuses = join(",", statuses);
    return OK;
}

function void clean() {
    shippedCount = 0;
    shippedTotal = 0D;
    lastOrderDate = zeroDate();
    clear(statuses);
}

