function integer transform() {
    $out.0.order_id = $in.0.order_id;
    $out.0.customer_id = $in.0.customer_id;
    $out.0.customer_tier = $in.1.tier;

    decimal rate = 0D;
    if ($in.1.tier.equals("GOLD")) {
        rate = 0.10D;
